p=argparse.ArgumentParser();p.add_argument('--executable',type=pathlib.Path,required=True);p.add_argument('--sdk-directory',type=pathlib.Path,required=True);p.add_argument('--directory',type=pathlib.Path,required=True);p.add_argument('--node',required=True);a=p.parse_args();receipt=a.directory.resolve();receipt.mkdir(parents=True,exist_ok=True);out=pathlib.Path(tempfile.mkdtemp(prefix='cases-',dir=receipt));sdk=a.sdk_directory.resolve();rows=[]
common='import{defineNativeSuite}from '+json.dumps((sdk/'native.js').as_uri())+";import{strict as assert}from'node:assert';"
def run(name,source,code=0,workers=1):
 root=out/name;root.mkdir();suite=root/'suite.mjs';suite.write_text(common+'\n'+source);v=subprocess.run([str(a.executable),'--node',a.node,'--host-script',str(sdk/'native-runner-host.js'),'--suite',str(suite),'--report',str(root/'actual.json'),'--junit',str(root/'actual.xml'),'--html',str(root/'actual.html'),'--workers',str(workers)],capture_output=True,timeout=15);(root/'stdout.bin').write_bytes(v.stdout);(root/'stderr.bin').write_bytes(v.stderr);assert v.returncode==code and not v.stderr,(name,v.returncode,v.stdout,v.stderr);r=json.loads((root/'actual.json').read_text());props={x.attrib['name']:x.attrib.get('value','')for x in ET.parse(root/'actual.xml').findall('.//property')};html=(root/'actual.html').read_text()
 for step in r['steps']:
  location=step.get('location')
  if location:
   prefix='native.step'+step['id']+'.location.';assert props[prefix+'line']==str(location['line']) and props[prefix+'column']==str(location['column']) and props[prefix+'origin']==location['origin'];assert 'Step source file'in html
 rows.append({'scope':name,'actualExitCode':v.returncode,'report':str(root/'actual.json')});return root,r
