root,r=run('original-timeout-retains-location-and-raw-receipt',"export default defineNativeSuite({tests:[{title:'actual timeout',run:async(_,i)=>{await assert.rejects(i.step('timed',async()=>{await new Promise(r=>setTimeout(r,40))},{timeout:10,location:{file:'timeout.ts',line:17,column:18}}),/timeout|deadline/i)}}]});");assert r['steps'][0]['status']=='timedOut' and r['steps'][0]['receipt']=='settled' and r['steps'][0]['location']['file']=='timeout.ts' and r['steps'][0]['callbackReceiptMonotonicMs']>=r['steps'][0]['endedMonotonicMs']
