root,r=run('invalid-options-never-admit-step',"export default defineNativeSuite({tests:[{title:'actual validation',run:(_,i)=>{for(const location of[{file:'',line:1,column:1},{file:'a',line:0,column:1},{file:'a',line:1,column:NaN}])assert.throws(()=>i.step('invalid',()=>assert.fail('no callback'),{location}));assert.throws(()=>i.step('invalid box type',()=>{}, {box:'true'}))}}]});");assert not r['steps'] and r['summary']['expected']==1
